(()=>{'use strict';let busy=false;const client=()=>window.supabase?.createClient(window.PATIYIZ_CONFIG.supabaseUrl,window.PATIYIZ_CONFIG.supabasePublishableKey);const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[c]));function validIban(value){const v=value.toUpperCase().replace(/\s/g,'');if(!/^TR[0-9]{24}$/.test(v))return false;const numeric=v.slice(4)+'2927'+v.slice(2,4);let remainder=0;for(const digit of numeric)remainder=(remainder*10+Number(digit))%97;return remainder===1}
function mount(){const shop=document.querySelector('.pati-calm-shop');if(!shop||shop.querySelector('#cashout-panel'))return;const panel=document.createElement('section');panel.id='cashout-panel';panel.className='pati-cashout-box';panel.innerHTML='<h2>Nakite Çevir</h2><p>Puanların için nakit talebi oluştur. Başvurular yönetici incelemesine gönderilir; başvurudaki puanlar hemen beklemeye alınır. Reddedilirse iade edilir; para yalnızca yönetici onayı ve gerçek banka transferi sonrasında ödenir.</p><form id="cashout-form"><label>Ad Soyad<input name="full_name" autocomplete="name" required minlength="5" maxlength="100" placeholder="Adın Soyadın"></label><label>IBAN<input name="iban" required inputmode="text" maxlength="34" placeholder="TR00 0000 0000 0000 0000 0000 00"></label><label>Çevirmek istediğin puan<select name="points"><option value="1000">1.000 puan — 100 TL talep</option><option value="2000">2.000 puan — 200 TL talep</option><option value="5000">5.000 puan — 500 TL talep</option><option value="10000">10.000 puan — 1.000 TL talep</option></select></label><button type="submit">Nakit talebi gönder</button><p id="cashout-message" role="status"></p></form><div id="cashout-history"></div><small>Talep tutarları incelemeye tabidir. Başvuru inceleme gerektirir ve ödeme garantisi oluşturmaz. Reddedilen talebin puanı iade edilir. Banka bilgilerin diğer kullanıcılara gösterilmez.</small>';shop.querySelector('.pati-calm-wallet')?.insertAdjacentElement('afterend',panel);loadHistory()}
async function loadHistory(){const host=document.getElementById('cashout-history');if(!host)return;try{const c=client();const r=await c.from('patiyiz_cashout_requests').select('amount_try,points_requested,status,created_at').order('created_at',{ascending:false}).limit(10);if(r.error)throw r.error;host.innerHTML='<h3>Talep geçmişim</h3>'+((r.data||[]).map(x=>'<div>'+Number(x.amount_try).toLocaleString('tr-TR')+' TL · '+esc(x.status==='pending'?'İncelemede':x.status==='approved'?'Onaylandı':x.status==='paid'?'Ödendi':'Reddedildi')+' <small>'+new Date(x.created_at).toLocaleDateString('tr-TR')+'</small></div>').join('')||'<p>Henüz talep oluşturmadın.</p>')}catch(e){host.textContent='Talep geçmişi yüklenemedi.'}}
document.addEventListener('submit',async e=>{if(e.target.id!=='cashout-form')return;e.preventDefault();if(busy)return;const f=e.target,m=document.getElementById('cashout-message');const name=f.elements.full_name.value.trim(),iban=f.elements.iban.value.replace(/\s/g,'').toUpperCase(),points=Number(f.elements.points.value);if(!validIban(iban)){m.textContent='26 karakterlik geçerli bir TR IBAN gir.';return}if(!confirm(points.toLocaleString('tr-TR')+' puan için '+(points/10).toLocaleString('tr-TR')+' TL nakit talebi gönderilsin mi? Bu ödeme garantisi değildir.'))return;busy=true;f.querySelector('button').disabled=true;try{const c=client(),r=await c.rpc('patiyiz_submit_cashout',{p_name:name,p_iban:iban,p_points:points});if(r.error)throw r.error;f.reset();m.textContent='Talebin incelemeye gönderildi. Seçilen puanlar beklemeye alındı; reddedilirse iade edilecek.';await loadHistory()}catch(error){m.textContent=error.message||'İşlem başarısız'}finally{busy=false;f.querySelector('button').disabled=false}});
new MutationObserver(()=>{if(document.querySelector('.pati-calm-shop:not(:has(#cashout-panel))'))mount()}).observe(document.getElementById('main-content'),{childList:true});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount);else mount();
})();